import express, { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';

interface TenantContext {
  tenantId: string;
  apiKey: string;
  isolationSeed: Buffer;
}

interface SessionToken {
  token: string;
  tenantId: string;
  createdAt: number;
  expiresAt: number;
}

const app = express();
app.use(express.json());

const tenantRegistry: Map<string, TenantContext> = new Map();
const activeSessions: Map<string, SessionToken> = new Map();

// Tenant provisioning with cryptographic isolation
function provisionTenant(tenantId: string): TenantContext {
  const isolationSeed = crypto.randomBytes(32);
  const apiKey = crypto.randomBytes(24).toString('base64url');
  const ctx: TenantContext = { tenantId, apiKey, isolationSeed };
  tenantRegistry.set(tenantId, ctx);
  return ctx;
}

// Derives a tenant-scoped entropy source for token generation
function deriveTenantEntropy(ctx: TenantContext, purpose: string): Buffer {
  return crypto.createHmac('sha256', ctx.isolationSeed)
    .update(purpose)
    .digest();
}

// Token generation engine - uses tenant-scoped derivation
class TokenEngine {
  private counter: number;
  private tenantEntropy: Buffer;
  private stateBuffer: Buffer;

  constructor(tenantEntropy: Buffer) {
    this.tenantEntropy = tenantEntropy;
    this.counter = 0;
    this.stateBuffer = Buffer.alloc(32);
    this.reseed();
  }

  private reseed(): void {
    // Mix tenant entropy with fresh randomness for state initialization
    const freshRandom = crypto.randomBytes(32);

    const hmac = crypto.createHmac('sha256', this.tenantEntropy);
    hmac.update(freshRandom);
    hmac.update(this.stateBuffer);
    this.stateBuffer = hmac.digest();
  }

  generateToken(): string {
    this.counter++;

    // Reseed every 100 tokens for forward secrecy
    if (this.counter % 100 === 0) {
      this.reseed();
    }

    // Generate token from fresh CSPRNG output mixed with state
    const freshEntropy = crypto.randomBytes(16);
    const counterBuf = Buffer.alloc(4);
    counterBuf.writeUInt32BE(this.counter);

    const output = crypto.createHmac('sha256', this.stateBuffer)
      .update(counterBuf)
      .update(freshEntropy)
      .digest();

    // Advance state with fresh randomness
    const stateAdvance = crypto.randomBytes(32);
    for (let i = 0; i < 32; i++) {
      this.stateBuffer[i] ^= output[i] ^ stateAdvance[i];
    }

    return output.toString('base64url').slice(0, 32);
  }
}

// Cache token engines per tenant for performance
const engineCache: Map<string, TokenEngine> = new Map();

function getTokenEngine(tenantId: string): TokenEngine | null {
  if (engineCache.has(tenantId)) {
    return engineCache.get(tenantId)!;
  }

  const ctx = tenantRegistry.get(tenantId);
  if (!ctx) return null;

  const entropy = deriveTenantEntropy(ctx, 'session-tokens');
  const engine = new TokenEngine(entropy);
  engineCache.set(tenantId, engine);
  return engine;
}

// Authentication middleware
function authenticateTenant(req: Request, res: Response, next: NextFunction): void {
  const apiKey = req.headers['x-api-key'] as string;
  if (!apiKey) {
    res.status(401).json({ error: 'Missing API key' });
    return;
  }

  const providedKey = Buffer.from(apiKey);

  let authenticated = false;
  for (const [id, ctx] of tenantRegistry) {
    const storedKey = Buffer.from(ctx.apiKey);
    // Guard against length mismatch: timingSafeEqual throws on differing
    // buffer lengths, which would crash the handler and leak length info.
    if (storedKey.length !== providedKey.length) {
      continue;
    }
    if (crypto.timingSafeEqual(storedKey, providedKey)) {
      (req as any).tenantId = id;
      authenticated = true;
      break;
    }
  }

  if (!authenticated) {
    res.status(403).json({ error: 'Invalid API key' });
    return;
  }
  next();
}

// Session creation endpoint
app.post('/api/sessions', authenticateTenant, (req: Request, res: Response) => {
  const tenantId = (req as any).tenantId;
  const engine = getTokenEngine(tenantId);

  if (!engine) {
    res.status(500).json({ error: 'Token engine unavailable' });
    return;
  }

  const token = engine.generateToken();
  const now = Date.now();
  const session: SessionToken = {
    token,
    tenantId,
    createdAt: now,
    expiresAt: now + 3600000
  };

  activeSessions.set(token, session);
  res.status(201).json({ sessionToken: token, expiresIn: 3600 });
});

// Session validation endpoint
app.get('/api/sessions/:token/validate', authenticateTenant, (req: Request, res: Response) => {
  const { token } = req.params;
  const tenantId = (req as any).tenantId;
  const session = activeSessions.get(token);

  if (!session || session.tenantId !== tenantId) {
    res.status(404).json({ valid: false });
    return;
  }

  if (Date.now() > session.expiresAt) {
    activeSessions.delete(token);
    res.status(410).json({ valid: false, reason: 'expired' });
    return;
  }

  res.json({ valid: true, tenantId: session.tenantId });
});

// Tenant isolation verification - admin endpoint
// Requires authentication to avoid exposing tenant identifiers publicly.
app.get('/api/admin/isolation-check', authenticateTenant, (req: Request, res: Response) => {
  const report: any[] = [];
  for (const [id] of tenantRegistry) {
    report.push({
      tenantId: id,
      status: 'isolated'
    });
  }
  res.json({ tenants: report, isolationStatus: 'verified' });
});

export default app;
